import './Registrar_Usuario.css';
import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { GuardrUsuario } from '../../../Redux/Actions/Usuario/Action-user';

const RegistrarUsuario = ({ setView }) => {
  const dispatch = useDispatch();
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: ''
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log(formData);
    dispatch(GuardrUsuario(formData));
  };

  return (
    <div className="body-empresa-register">
      <div>
        <h2 className="Titulos">Registro de Usuario</h2>
        <form onSubmit={handleSubmit}>
          <div className="input-group">
            <label>
              Nombre:
              <input
                type="text"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
              />
            </label>
          </div>
          <div className="input-group">
            <label>
              Apellido:
              <input
                type="text"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
              />
            </label>
          </div>
          <div className="input-group">
            <label>
              Email:
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
              />
            </label>
          </div>
          <div className="input-group">
            <label>
              Contraseña:
              <input
                type="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
              />
            </label>
          </div>
          <div onClick={handleSubmit} className="btn-Enviar">Registrarse</div>
        </form>
      </div>
      <div onClick={() => setView("login")} className="btn-Link">Ya tienes cuenta? Iniciar sesión</div>
    </div>
  );
};

export default RegistrarUsuario;
